    major, minor, patch = sv
    if level == 'major':
        new = f"{major + 1}.0.0"
    elif level == 'minor':
        new = f"{major}.{minor + 1}.0"
    else:
        new = f"{major}.{minor}.{patch + 1}"

    services[service]['version'] = new
    with open(MANIFEST_PATH, 'w') as f:
        yaml.safe_dump(data, f, sort_keys=False)
    print(f"BUMP {service} {old} -> {new}")

